{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $reader = New-Object System.IO.StreamReader("<repo>-bench\ab-continuation\sandboxes\formal-case-05-A\input\session.jsonl"); $lines = @(); while (($line = $reader.ReadLine()) -ne $null) { $lines += $line }; $reader.Close()
function Txt($o) { ($o.payload.content | Where-Object { $_.text } | ForEach-Object { $_.text }) -join "`n" }
"##### REASONING RECORDS (ordinal : type : summary)"
foreach ($i in 0..($lines.Count-1)) {
  try { $o = $lines[$i] | ConvertFrom-Json } catch { continue }
  if ($o.type -ne 'response_item') { continue }
  $p = $o.payload
  if ($p.type -eq 'reasoning') {
    $sum = $p.summary
    if (-not $sum) { $sum = (($p.content | Where-Object { $_.type -eq 'summary_text' } | ForEach-Object { $_.text }) -join ' ') }
    $enc = $p.encrypted_content
    "ord=$($o.ordinal) len=$($lines[$i].Length) summary=$sum enc=$enc"
  }
}
"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $reader = New-Object System.IO.StreamReader("<repo>-bench\ab-continuation\sandboxes\formal-case-05-A\input\session.jsonl"); $lines = @(); while (($line = $reader.ReadLine()) -ne $null) { $lines += $line }; $reader.Close()
foreach ($i in 0..($lines.Count-1)) {
  try { $o = $lines[$i] | ConvertFrom-Json } catch { continue }
  if ($o.type -ne 'response_item') { continue }
  $p = $o.payload
  if ($p.type -eq 'custom_tool_call') {
    $name = $p.name; $args = $p.arguments
    "CALL ord=$($o.ordinal) name=$name args=$($args | ConvertTo-Json -Compress -Depth 4)"
  } elseif ($p.type -eq 'custom_tool_call_output') {
    $txt = ($p.content | Where-Object { $_.type -eq 'output_text' } | ForEach-Object { $_.text }) -join "`n"
    if (-not $txt) { $txt = $p.output }
    if ($txt.Length -gt 400) { $txt = $txt.Substring(0,400) + " ...[+$($txt.Length-400) chars]" }
    "OUT ord=$($o.ordinal) tool_id=$($p.call_id) text=$txt"
  }
}
"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $reader = New-Object System.IO.StreamReader("<repo>-bench\ab-continuation\sandboxes\formal-case-05-A\input\session.jsonl"); $lines = @(); while (($line = $reader.ReadLine()) -ne $null) { $lines += $line }; $reader.Close()
$seq = 0
foreach ($i in 0..($lines.Count-1)) {
  try { $o = $lines[$i] | ConvertFrom-Json } catch { continue }
  if ($o.type -ne 'response_item') { continue }
  $p = $o.payload
  if ($p.type -eq 'custom_tool_call') {
    $seq++
    $cmd = $p.input
    if (-not $cmd) { $cmd = ($p.arguments | ConvertTo-Json -Compress -Depth 5) }
    if ($cmd.Length -gt 500) { $cmd = $cmd.Substring(0,500) + " ...[+$($cmd.Length-500) chars]" }
    "### [$seq] CALL ord=$($o.ordinal) name=$($p.name)"
    $cmd
  } elseif ($p.type -eq 'custom_tool_call_output') {
    $out = ($p.output | ForEach-Object { $_.text }) -join "`n"
    if (-not $out) { $out = $p.output }
    if ($out.Length -gt 900) { $out = $out.Substring(0,900) + "`n...[+$($out.Length-900) chars truncated]" }
    "###   OUTPUT ord=$($o.ordinal):"
    $out
    ""
  }
}
"}

