{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $reader = New-Object System.IO.StreamReader("<repo>-bench\ab-continuation\sandboxes\formal-case-05-A\input\session.jsonl"); $lines = @(); while (($line = $reader.ReadLine()) -ne $null) { $lines += $line }; $reader.Close()
$names = @{}
foreach ($l in $lines) { try { $o = $l | ConvertFrom-Json } catch { continue }; if ($o.type -eq 'response_item' -and $o.payload.type -eq 'custom_tool_call') { $n = $o.payload.name; if ($names.ContainsKey($n)) { $names[$n]++ } else { $names[$n] = 1 } } }
